    colored = neighbor_colors.sum(axis=1)
    return colored / np.maximum(degree, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation degree normalised by how many colours a candidate could still legally take (used colours minus blocked), i.e. remaining freedom per blocked colour."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = (neighbor_colors > 0)
    sat = blocked.sum(axis=1).astype(float)          # distinct colours already used by neighbours
    free = c - sat                                   # colours still available to this candidate
    # how much of the palette is still reachable, relative to the blocked pressure
    return (free - sat) / max(c, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Among uncoloured candidates, how connected each is to the other candidates (uncoloured subgraph degree share)."""
    k = adjacency.shape[0]
    if k <= 1:
        return np.zeros(k)
    uncolored_deg = adjacency.sum(axis=1).astype(float)
    return uncolored_deg / max(k - 1, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Mean scarcity (inverse colour size, max-normalised) over the distinct colours blocking each candidate."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    sizes = np.asarray(color_sizes, dtype=float)
    w = 1.0 / np.maximum(sizes, 1.0)
    w = w / (w.max() + 1e-12)
    blocked = neighbor_colors > 0
    weighted = blocked @ w
    count = blocked.sum(axis=1)
    return weighted / np.maximum(count, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """1 - (first free colour index, or c if none free) / (c + 1), per candidate."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    blocked = neighbor_colors > 0
    free = ~blocked
    any_free = free.any(axis=1)
    # argmax on all-False rows returns 0; mask those out and use c instead.
    first_free = free.argmax(axis=1)
    T = np.where(any_free, first_free, c)
    return 1.0 - T / (c + 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For each candidate: the size of the smallest used colour class among its coloured neighbours — how 'cheap' the colours it competes with are, since sitting next to a small colour class leaves large classes free for its neighbours."""
    k = neighbor_colors.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = neighbor_colors > 0                       # (k, c)
    sizes = np.asarray(color_sizes, dtype=float)        # (c,)
    total = sizes.sum()
    if total <= 0:
        return np.zeros(k)
    # normalised colour-class size, in (0, 1]
    norm_sizes = sizes / total
    # for each candidate, the minimum normalised size among the colours it is blocked by
    big = np.where(blocked, norm_sizes[None, :], np.inf)
    min_size = big.min(axis=1)
    min_size = np.where(np.isfinite(min_size), min_size, 0.0)
    # more blocked colours with tiny classes -> small value; scale into [0,1]
    return np.nan_to_num(min_size, nan=0.0, posinf=1.0, neginf=0.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation (fraction of used colours blocking the candidate) times a palette-size regime flip tanh((c0-c)/2), c0=max(1,n/20)."""
    k = neighbor_colors.shape[0]
    if k == 0:
        return np.zeros(0)
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = (neighbor_colors > 0)
    sat = blocked.sum(axis=1) / float(c)
    n = k + int(color_sizes.sum())
    c0 = max(1.0, n / 20.0)
    regime = np.tanh((c0 - c) / 2.0)
    return sat * regime

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Uncoloured-degree minus the mean uncoloured-degree of its uncoloured neighbours, scaled by total degree."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    uncol_deg = adjacency.sum(axis=1).astype(float)
    mean_nb = (adjacency @ uncol_deg) / np.maximum(uncol_deg, 1.0)
    diff = uncol_deg - mean_nb
    return np.clip(diff / np.maximum(degree.astype(float), 1.0), -1.0, 1.0)
